CREATE VIEW "public"."argument_evaluations_in_force" AS (select "id", "argument_id", "verdict", "decisive", "content", "assessment_id", "estimate_id", "is_current", "created_by", "created_at" from "argument_evaluations" where "argument_evaluations"."is_current" = true);--> statement-breakpoint
CREATE VIEW "public"."assessments_in_force" AS (select "id", "claim_id", "status", "confidence", "claim_credence", "summary", "reasoning_trace", "marginal_yield", "model", "funded_by_job_id", "skills", "run_id", "is_current", "subclaim_summary", "trigger", "trigger_context", "assessed_at", "relabeled_from" from "assessments" where "assessments"."is_current" = true);--> statement-breakpoint
CREATE VIEW "public"."quantity_estimates_in_force" AS (select "id", "claim_id", "estimate", "summary", "work", "marginal_yield", "model", "funded_by_job_id", "is_current", "trigger", "trigger_context", "assessed_at" from "quantity_estimates" where "quantity_estimates"."is_current" = true);--> statement-breakpoint
CREATE VIEW "public"."question_assessments_in_force" AS (select "id", "claim_id", "standing", "favored_claim_ids", "summary", "reasoning_trace", "incomplete", "confidence", "marginal_yield", "model", "funded_by_job_id", "run_id", "is_current", "trigger", "trigger_context", "assessed_at" from "question_assessments" where "question_assessments"."is_current" = true);